:root {
  --ink: #26333b;
  --muted: #6f7a7d;
  --paper: #fffdf7;
  --line: #d9d4c5;
  --sage: #dce7dc;
  --sage-ink: #3e6654;
  --ochre: #d69a35;
  --ochre-soft: #fff0cc;
  --deep-green: #315f50;
  --white: #ffffff;
}

.kit-card {
  box-sizing: border-box;
  width: 480px;
  padding: 16px;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.kit-header {
  display: flex;
  align-items: center;
  gap: 10px;
}

.thread-mark {
  width: 38px;
  height: 38px;
  background: var(--ochre-soft);
  border-radius: 12px;
  display: grid;
  place-items: center;
  font-size: 20px;
}

.kit-heading {
  flex: 1;
  min-width: 0;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.8px;
}

.kit-title {
  margin: 0;
  font-size: 20px;
  font-weight: 750;
  line-height: 1.1;
}

.status {
  padding: 5px 8px;
  color: var(--sage-ink);
  background: var(--sage);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
}

.kit-body {
  display: grid;
  grid-template-columns: 126px 1fr;
  gap: 14px;
  align-items: stretch;
}

.spool {
  box-sizing: border-box;
  margin: 0;
  padding: 10px;
  background: var(--ochre-soft);
  border: 1px solid var(--ochre);
  border-radius: 14px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.spool-core {
  width: 46px;
  height: 46px;
  flex: 0 0 auto;
  color: var(--white);
  background: var(--ochre);
  border: 5px solid var(--paper);
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 15px;
  font-weight: 800;
}

.spool-label {
  color: var(--sage-ink);
  font-size: 11px;
  font-weight: 700;
  line-height: 1.25;
}

.kit-details {
  min-width: 0;
}

.kit-copy {
  margin: 1px 0 8px;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.35;
}

.spec-list {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 3px;
}

.spec-row {
  padding-top: 3px;
  border-top: 1px solid var(--line);
  display: flex;
  justify-content: space-between;
  gap: 12px;
  color: var(--muted);
  font-size: 11px;
}

.spec-row strong {
  color: var(--ink);
  font-weight: 700;
}

.kit-footer {
  padding-top: 12px;
  border-top: 1px solid var(--line);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.tags {
  display: flex;
  gap: 6px;
}

.tag {
  padding: 4px 7px;
  color: var(--sage-ink);
  background: var(--sage);
  border-radius: 6px;
  font-size: 10px;
  font-weight: 700;
}

.reserve-button {
  padding: 8px 12px;
  color: var(--white);
  background: var(--deep-green);
  border: 1px solid var(--deep-green);
  border-radius: 8px;
  font-size: 12px;
  font-weight: 700;
}
